var LANGS = ["ar","nl","en","tr","de","fr","es","pt","zh"];
var LANG_INFO = { ar:["ar-u-nu-latn","ar-SA","Arabic (simple, friendly Gulf-style Arabic)"], nl:["nl-NL","nl-NL","Dutch"], en:["en-GB","en-US","English"],
  tr:["tr-TR","tr-TR","Turkish"], de:["de-DE","de-DE","German"], fr:["fr-FR","fr-FR","French"], es:["es-ES","es-ES","Spanish"], pt:["pt-BR","pt-BR","Brazilian Portuguese"], zh:["zh-CN","zh-CN","Simplified Chinese"] };
function langName(){ return (LANG_INFO[LANG] || LANG_INFO.en)[2]; }
var LANG = LANGS.indexOf(state.lang) >= 0 ? state.lang : "ar";
function t(k){
  var d = (window.I18N || {})[LANG] || {};
  if (d[k] != null) return d[k];
  var e = (window.I18N || {}).en || {}, a = (window.I18N || {}).ar || {};
  if (LANG !== "ar" && e[k] != null) return e[k];
  return a[k] != null ? a[k] : k;
}
function tx(tid, f, fb){
  if (LANG === "ar" || !tid) return fb;
  var d = ((window.TRX || {})[LANG] || {})[tid];
  return (d && d[f] != null) ? d[f] : fb;
}
function mName(k){
  if (LANG !== "ar"){ var m = (window.MUSCLES_L || {})[LANG]; if (m && m[k]) return m[k]; }
  return MUSCLE_AR[k] || k;
}
function sep(){ return LANG === "ar" ? "، " : ", "; }
/* العنوان الكبير + السطر الصغير تحته */
function names2(tid, ar, en){
  if (LANG === "ar") return [ar, en];
  if (LANG !== "en") { var n = tx(tid, "n", en); return [n, n === en ? "" : en]; }
  return [tx(tid, "n", en), ""];
}
/* «4 جولات · 6–8 تكرار» بدل «4×6–8» */
function srParts(p){
  var n = +p.sets || 0, r = String(p.reps), m, rv, ru;
  if ((m = r.match(/^(.+?)\s*ث$/))){ rv = m[1]; ru = t("srSec"); }
  else if ((m = r.match(/^(.+?)\s*د$/))){ rv = m[1]; ru = t("srMin"); }
  else if ((m = r.match(/^(.+?)\s*م$/))){ rv = m[1]; ru = t("srM"); }
  else { rv = r; ru = t("srReps"); }
  return { n:n, su:t(n === 1 ? "srSet1" : "srSets"), rv:rv, ru:ru };
}
function setsRepsHTML(p){
  var q = srParts(p);
  return '<span class="load num sr"><span><b>' + q.n + '</b> ' + q.su + '</span><span><b>' + xEsc(q.rv) + '</b> ' + q.ru + '</span></span>';
}
function setsRepsInline(p){
  var q = srParts(p);
  return '<span class="sr-inline"><b>' + q.n + '</b> ' + q.su + ' · <b>' + xEsc(q.rv) + '</b> ' + q.ru + '</span>';
}
function fmtReps(r){
  r = String(r);
  if (LANG === "ar") return r;
  return r.replace(/ث$/, "s").replace(/د$/, " min").replace(/م$/, " m");
}
function dayText(d){
  if (LANG === "ar") return [d.name, d.focus];
  var L = ((window.DAYS_L || {})[LANG] || {})[d.key];
  return L || [d.name, d.focus];
}
function applyStatic(){
  var root = document.getElementById("root");
  root.setAttribute("dir", LANG === "ar" ? "rtl" : "ltr");
  root.setAttribute("lang", LANG);
  document.documentElement.setAttribute("lang", LANG);
  document.title = t("brand");
  root.querySelectorAll("[data-i18n]").forEach(function(el){ el.textContent = t(el.getAttribute("data-i18n")); });
  root.querySelectorAll("[data-i18n-html]").forEach(function(el){ el.innerHTML = t(el.getAttribute("data-i18n-html")); });
  root.querySelectorAll("[data-i18n-aria]").forEach(function(el){ el.setAttribute("aria-label", t(el.getAttribute("data-i18n-aria"))); });
  root.querySelectorAll("[data-i18n-title]").forEach(function(el){ var v = t(el.getAttribute("data-i18n-title")); el.title = v; el.setAttribute("aria-label", v); });
  root.querySelectorAll("[data-lang]").forEach(function(b){ b.setAttribute("aria-pressed", String(b.getAttribute("data-lang") === LANG)); });
  root.querySelectorAll("[data-lang-sel]").forEach(function(sel){ sel.value = LANG; });
  if (timer && timer.hidden){ timerName.textContent = t("timerRest"); document.getElementById("timerSub").textContent = t("nextRound"); }
}

