// مفاتيح البرنامج ← أسماء الأجزاء داخل الرسم
var SLUG = {
  chest: ["chest"],
  shoulders: ["deltoids"],
  reardelts: ["deltoids"],
  triceps: ["triceps"],
  biceps: ["biceps"],
  forearms: ["forearm"],
  abs: ["abs", "obliques"],
  traps: ["trapezius"],
  lats: ["upper-back"],
  lowerback: ["lower-back"],
  glutes: ["gluteal"],
  quads: ["quadriceps"],
  hamstrings: ["hamstring"],
  calves: ["calves"]
};

function slugSet(keys){
  var out = {};
  (keys || []).forEach(function(k){
    (SLUG[k] || []).forEach(function(sl){ out[sl] = 1; });
  });
  return out;
}

// يبني رسم جهة واحدة؛ لا يُعاد بناؤه إلا عند تغيّر العضلات
function anatomySvg(side, primary, secondary, cls, label, stab){
  /* صورة الجسم من Lyfta مع العضلات ملوّنة (bodies.js) */
  var BI = window.BODY_IMG;
  if (BI){
    var bk = [(primary || []).join(","), (secondary || []).join(","), (stab || []).join(",")].join("|");
    if (!BI[bk] && window.BODY_LAYERS) return bodyStack(side, primary, secondary, stab, cls, label);
    var rec = BI[bk] || BI["||"];
    if (rec){
      var img = document.createElement("img");
      img.className = "bodyimg " + (cls || "");
      img.src = rec[side === "back" ? "back" : "front"];
      img.alt = label || "";
      img.decoding = "async";
      return img;
    }
  }
  var A = window.ANATOMY;
  var host = document.createElement("div");
  if (!A) return host;
  var isBack = side === "back";
  var parts = isBack ? A.back : A.front;
  var vb = isBack ? A.viewBox.back : A.viewBox.front;
  var hot = slugSet(primary), warm = slugSet(secondary), cool = slugSet(stab);

  // 1) الخط الخارجي أولاً بتعبئة كاملة
  var body = '<path class="bodyBase" d="' + (isBack ? A.outlineBack : A.outlineFront) + '"/>';

  // 2) ثم العضلات فوقه
  parts.forEach(function(part){
    var tier = hot[part.slug] ? " p1" : (warm[part.slug] ? " p2" : (cool[part.slug] ? " p3" : ""));
    part.path.common.concat(part.path.left, part.path.right).forEach(function(d){
      body += '<path class="bodyPart' + tier + '" d="' + d + '"/>';
    });
  });

  host.innerHTML = '<svg class="' + (cls || "") + '" viewBox="' + vb +
                   '" role="img" aria-label="' + (label || "") + '">' + body + '</svg>';
  return host.firstChild;
}

// خريطة مصغّرة: الجهتان جنباً إلى جنب داخل البطاقة
function muscleMap(primary, secondary, stab){
  var names = (primary || []).map(mName).join(sep());
  var box = document.createElement("div");
  box.className = "map";
  [["front", t("front")], ["back", t("back")]].forEach(function(pair){
    var col = document.createElement("div");
    col.className = "mcol";
    col.appendChild(anatomySvg(pair[0], primary, secondary, "", t("primaryMuscles") + ": " + names, stab));
    var cap = document.createElement("span");
    cap.textContent = pair[1];
    col.appendChild(cap);
    box.appendChild(col);
  });
  return box;
}


