/* نحوّل الفيديو لملف في الذاكرة مرة وحدة، عشان يشتغل على طول بدون تعليق */
var VCACHE = {};
function dataToBlobURL(d){
  var comma = d.indexOf(","), mime = d.slice(5, d.indexOf(";"));
  var bin = atob(d.slice(comma + 1)), arr = new Uint8Array(bin.length);
  for (var i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
  return URL.createObjectURL(new Blob([arr], { type:mime }));
}
function getVideo(key){
  if (VCACHE[key]) return VCACHE[key];
  if (isLibKey(key)){ VCACHE[key] = libVideo(+key.slice(1)); VCACHE[key].catch(function(){ delete VCACHE[key]; }); return VCACHE[key]; }
  var src = videoSrc(key);
  if (!src) return null;
  var pr;
  if (src.indexOf("data:") === 0){
    pr = new Promise(function(res){ try { res(dataToBlobURL(src)); } catch(e){ res(src); } });
  } else if (window.fetch && window.URL && URL.createObjectURL){
    pr = fetch(src).then(function(r){ if (!r.ok) throw new Error("x"); return r.blob(); })
                   .then(function(b){ return URL.createObjectURL(b); })
                   .catch(function(){ return src; });
  } else pr = Promise.resolve(src);
  VCACHE[key] = pr;
  return pr;
}
