var CAN_MP4 = (function(){ try { return !!document.createElement("video").canPlayType('video/mp4; codecs="avc1.4D401F"'); } catch(e){ return true; } })();
function videoSrc(key){
  if (isLibKey(key)) return "lib:" + key;
  var d = (window.VIDEO_DATA || {})[key];
  if (d) return d.mp4;
  var f = VIDEO_FILES[key];
  if (!f) return null;
  if (window.VIDEO_BASE) return window.VIDEO_BASE + f.replace(/^videos\//, "");
  return f;
}
var PL = { item:null, raf:0, t:0, last:0, playing:false, speed:1, sound:false, steps:[], total:0, spoken:-1 };
var PL_INTRO = 2.2, PL_SLOW = 2.0, PL_HOLD = 0.4, PL_FAST = 1.1, PL_REPS = 4;
var PL_REP = PL_SLOW + PL_HOLD + PL_FAST + 0.3;
var ICON_PLAY = '<svg class="fillic" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>';
var ICON_PAUSE = '<svg class="fillic" viewBox="0 0 24 24"><path d="M7 5h4v14H7zM13 5h4v14h-4z"/></svg>';
var ICON_SND = '<svg viewBox="0 0 24 24"><path d="M4 9v6h4l5 4V5L8 9z"/><path d="M16.5 8.5a5 5 0 0 1 0 7M19 6a8.5 8.5 0 0 1 0 12"/></svg>';
var ICON_MUTE = '<svg viewBox="0 0 24 24"><path d="M4 9v6h4l5 4V5L8 9z"/><path d="M17 9l5 6M22 9l-5 6"/></svg>';

function splitCue(txt){
  return String(txt).split(/(?<=[.!؟?])\s+|\s+—\s+|؛\s*/).map(function(x){ return x.trim(); }).filter(Boolean);
}
function plVoice(){
  if (!("speechSynthesis" in window)) return null;
  var want = LANG;
  var vs = speechSynthesis.getVoices() || [];
  var hit = vs.filter(function(v){ return (v.lang || "").toLowerCase().indexOf(want) === 0; });
  return hit[0] || null;
}
function plSpeak(text){
  if (!PL.sound || !("speechSynthesis" in window)) return;
  try {
    speechSynthesis.cancel();
    var u = new SpeechSynthesisUtterance(text);
    var v = plVoice();
    u.lang = (LANG_INFO[LANG] || LANG_INFO.en)[1];
    if (v) u.voice = v;
    u.rate = 0.95 * PL.speed;
    speechSynthesis.speak(u);
  } catch (e) {}
}
function plStopVoice(){ try { if ("speechSynthesis" in window) speechSynthesis.cancel(); } catch (e) {} }

function openPlayer(item){
  if (!item) return;
  PL.item = item;
  var tid = item.tid || item.id;
  var nm = names2(tid, item.ar, item.en);
  document.getElementById("plTitle").firstChild.nodeValue = nm[0];
  document.getElementById("plSub").textContent = nm[1];
  var fr = (window.EXFRAMES || {})[item.key] || [];
  document.getElementById("plF0").src = fr[0] || "";
  document.getElementById("plF1").src = fr[1] || fr[0] || "";
  var an = document.getElementById("plAnat");
  an.innerHTML = "";
  an.appendChild(anatomySvg("front", item.muscles, item.sec, "", t("front"), item.stab));
  an.appendChild(anatomySvg("back", item.muscles, item.sec, "", t("back"), item.stab));

  var cue = item.cueI ? t(item.cueI) : tx(tid, "c", item.cue);
  var main = (item.muscles || []).map(mName).join(sep());
  PL.steps = [nm[0] + (main ? " — " + t("lgP") + ": " + main : "")].concat(splitCue(cue));
  PL.speech = nm[0] + ". " + cue;
  PL.total = PL_INTRO + PL_REPS * PL_REP;
  PL.t = 0; PL.spoken = -1; PL.vclock = 0; PL.last = performance.now();

  var v = (VIDEOS[item.key] || {});
  var vid = v[LANG] || v.en;
  var yl = document.getElementById("plYt");
  if (vid){ yl.hidden = false; yl.href = "https://www.youtube.com/watch?v=" + encodeURIComponent(vid); yl.textContent = t("ytReal"); }
  else yl.hidden = true;

  var vsrc = videoSrc(item.key), vel = document.getElementById("plVid");
  PL.video = !!vsrc;
  document.getElementById("plStage").classList.toggle("vmode", PL.video);
  document.querySelector(".pl-card").classList.toggle("vonly", PL.video);
  vel.hidden = !PL.video;
  var cr = document.getElementById("plCredit");
  if (PL.video){
    var box = vel.parentNode;
    vel.pause();
    vel.poster = VIDEO_POSTER[item.key] || "";
    PL.vready = false;
    box.classList.add("loading");
    var myItem = item;
    getVideo(item.key).then(function(url){
      if (PL.item !== myItem) return;
      var go = function(){
        PL.vready = true; box.classList.remove("loading");
        vel.playbackRate = PL.speed;
        if (PL.playing){ var q = vel.play(); if (q && q.catch) q.catch(function(){}); }
      };
      if (vel.getAttribute("data-key") === myItem.key && vel.readyState >= 3){ vel.currentTime = 0; go(); return; }
      vel.setAttribute("data-key", myItem.key);
      vel.addEventListener("canplay", function h(){ vel.removeEventListener("canplay", h); go(); });
      vel.src = url; vel.load();
    });
    cr.hidden = false; cr.textContent = fill(t("videoCredit"), { c:VIDEO_CREDIT[item.key] || "" }) + (VIDEO_NOTE[item.key] ? " · " + t(VIDEO_NOTE[item.key]) : "");
    document.getElementById("plStage").classList.toggle("wide", !!VIDEO_WIDE[item.key]);
  } else { vel.pause(); vel.parentNode.classList.remove("loading"); cr.hidden = true; }

  plUpdateSound();
  document.getElementById("plSpeed").textContent = PL.speed === 1 ? "1×" : "0.75×";
  document.getElementById("player").hidden = false;
  plRender(0);
  plPlay();
  document.getElementById("plPlay").focus();
}
function plUpdateSound(){
  var b = document.getElementById("plSound");
  if (!b) return;
  b.innerHTML = (PL.sound ? ICON_SND : ICON_MUTE) + '<span>' + t("sound") + '</span>';
  b.setAttribute("aria-pressed", String(PL.sound));
  var note = document.getElementById("plNote");
  if (!("speechSynthesis" in window)) note.textContent = t("noVoice");
  else if (PL.sound && !plVoice()) note.textContent = t("noVoice");
  else note.textContent = "";
}
function plSetPlayBtn(){
  var b = document.getElementById("plPlay");
  b.innerHTML = (PL.playing ? ICON_PAUSE : ICON_PLAY) + '<span>' + (PL.playing ? t("pause") : t("play")) + '</span>';
  document.getElementById("plBig").hidden = PL.playing;
}
function plPlay(){
  if (PL.video){
    var v = document.getElementById("plVid");
    PL.playing = true; plSetPlayBtn();
    if (PL.vready){ var pr = v.play(); if (pr && pr.catch) pr.catch(function(){ PL.playing = false; plSetPlayBtn(); }); }
    cancelAnimationFrame(PL.raf); PL.raf = requestAnimationFrame(plTick);
    return;
  }
  if (PL.t >= PL.total) PL.t = 0;
  PL.playing = true; PL.last = performance.now();
  if (PL.t < 0.1) { PL.spoken = 0; plSpeak(PL.speech); }
  else if ("speechSynthesis" in window && PL.sound) { try { speechSynthesis.resume(); } catch(e){} }
  plSetPlayBtn();
  cancelAnimationFrame(PL.raf);
  PL.raf = requestAnimationFrame(plTick);
}
function plPause(){
  PL.playing = false; cancelAnimationFrame(PL.raf);
  if (PL.video) document.getElementById("plVid").pause();
  try { if ("speechSynthesis" in window) speechSynthesis.pause(); } catch(e){}
  plSetPlayBtn();
}
function plTick(now){
  if (!PL.playing) return;
  if (PL.video){
    var v = document.getElementById("plVid");
    var d = v.duration || 7, ct = v.currentTime || 0;
    // الفيديو يعيد لحاله؛ الشرح المكتوب يتغيّر كل ~3.5 ثانية
    PL.vclock = (PL.vclock || 0) + Math.min(0.1, (now - (PL.last || now)) / 1000) * PL.speed;
    PL.last = now;
    var k = Math.floor(PL.vclock / 3.5) % PL.steps.length;
    document.getElementById("plCap").textContent = PL.steps[k] || "";
    document.getElementById("plProg").style.width = (ct / d * 100).toFixed(2) + "%";
    PL.raf = requestAnimationFrame(plTick);
    return;
  }
  var dt = Math.min(0.1, (now - PL.last) / 1000) * PL.speed;
  PL.last = now;
  PL.t += dt;
  if (PL.t >= PL.total){ PL.t = PL.total; plRender(PL.t); PL.playing = false; plSetPlayBtn(); return; }
  plRender(PL.t);
  PL.raf = requestAnimationFrame(plTick);
}
function ease(x){ return x < .5 ? 2 * x * x : 1 - Math.pow(-2 * x + 2, 2) / 2; }
function plRender(tt){
  if (PL.video){
    document.getElementById("plPhase").textContent = "";
    document.getElementById("plRep").textContent = "";
    document.getElementById("plCap").textContent = PL.steps[0] || "";
    document.getElementById("plProg").style.width = "0%";
    return;
  }
  var mix = 0, phase = "", pc = "#9AA6B2", rep = "", flex = false;
  if (tt >= PL_INTRO){
    var r = tt - PL_INTRO, n = Math.floor(r / PL_REP), x = r - n * PL_REP;
    rep = fill(t("repOf"), { n:Math.min(n + 1, PL_REPS), m:PL_REPS });
    if (x < PL_SLOW){ mix = ease(x / PL_SLOW); phase = t("phSlow"); pc = "#7FB7FF"; }
    else if (x < PL_SLOW + PL_HOLD){ mix = 1; phase = t("phHold"); pc = "#EFC21C"; }
    else if (x < PL_SLOW + PL_HOLD + PL_FAST){ mix = 1 - ease((x - PL_SLOW - PL_HOLD) / PL_FAST); phase = t("phFast"); pc = "#E83A24"; flex = true; }
    else { mix = 0; phase = t("phFast"); pc = "#E83A24"; }
  } else phase = t("phSetup");
  var f1 = document.getElementById("plF1");
  f1.style.opacity = mix.toFixed(3);
  document.getElementById("plF0").style.transform = "scale(" + (1.02 + mix * 0.02).toFixed(3) + ")";
  f1.style.transform = "scale(" + (1.04 - mix * 0.02).toFixed(3) + ")";
  var ph = document.getElementById("plPhase");
  ph.textContent = phase; ph.style.setProperty("--pc", pc);
  document.getElementById("plRep").textContent = rep;
  document.getElementById("plAnat").classList.toggle("flex", flex);
  var k = Math.min(PL.steps.length - 1, Math.floor(tt / PL.total * PL.steps.length));
  document.getElementById("plCap").textContent = PL.steps[Math.max(0, k)] || "";
  document.getElementById("plProg").style.width = (tt / PL.total * 100).toFixed(2) + "%";
}
function closePlayer(){
  plPause(); plStopVoice();
  document.getElementById("player").hidden = true;
}
document.getElementById("plPlay").addEventListener("click", function(){ PL.playing ? plPause() : plPlay(); });
document.getElementById("plBig").addEventListener("click", function(){ plPlay(); });
document.getElementById("plRestart").addEventListener("click", function(){
  plStopVoice(); PL.t = 0; PL.vclock = 0;
  if (PL.video) document.getElementById("plVid").currentTime = 0;
  plPlay();
});
if (document.getElementById("plSound")) document.getElementById("plSound").addEventListener("click", function(){
  PL.sound = !PL.sound; plUpdateSound();
  if (!PL.sound) plStopVoice(); else if (PL.playing) plSpeak(PL.speech);
});
document.getElementById("plSpeed").addEventListener("click", function(){
  PL.speed = PL.speed === 1 ? 0.75 : 1;
  document.getElementById("plVid").playbackRate = PL.speed;
  this.textContent = PL.speed === 1 ? "1×" : "0.75×";
});
document.getElementById("plClose").addEventListener("click", closePlayer);
document.getElementById("plBg").addEventListener("click", closePlayer);
document.addEventListener("keydown", function(ev){
  if (document.getElementById("player").hidden) return;
  if (ev.key === "Escape") closePlayer();
  if (ev.key === " " && ev.target.tagName !== "BUTTON"){ ev.preventDefault(); PL.playing ? plPause() : plPlay(); }
});
if ("speechSynthesis" in window){ try { speechSynthesis.onvoiceschanged = function(){ if (!document.getElementById("player").hidden) plUpdateSound(); }; } catch(e){} }

/* ---------------- exercise reel ---------------- */
/* صورة ثابتة للتمرين: لقطة من فيديو التشريح إن وُجد، وإلا الصورة الأولى */
function reel(key){
  var poster = (typeof CARD_POSTER !== "undefined") ? CARD_POSTER[key] : null;
  var src = poster || ((window.EXFRAMES || {})[key] || [])[0];
  var box = document.createElement("div");
  box.className = "reel" + (poster ? " vid" : "");
  if (!src) return box;
  var img = document.createElement("img");
  img.className = "shot";
  img.src = src;
  img.alt = "";
  img.decoding = "async";
  box.appendChild(img);
  return box;
}

