/* البرنامج حسب الملف: عدد الأيام + تبديل التمارين حسب الإصابة */
var BASE_DAYS = DAYS;
function exById(id){ var r = null; BASE_DAYS.forEach(function(d){ d.ex.forEach(function(x){ if (x.id === id) r = x; }); }); return r; }
function dayById(k){ for (var i = 0; i < BASE_DAYS.length; i++) if (BASE_DAYS[i].key === k) return BASE_DAYS[i]; return null; }
function cloneEx(src, id){
  var c = Object.assign({}, src, { id:id, tid:src.id });
  LANGS.forEach(function(l){ var T = (window.TRX || {})[l]; if (l !== "ar" && T && T[src.id] && !T[id]) T[id] = T[src.id]; });
  return c;
}
function buildDays(){
  var P = PROF(), n = +P.days || 4, inj = P.inj || {}, list;
  var fb = function(key, name, focus, ids){ return { key:key, name:name, focus:focus, rest:false, ex:ids.map(exById) }; };
  if (n === 3){
    list = [
      fb("F1", "جسم كامل 1", "سكوات · صدر · ظهر", ["b1","a1","c2","b4","a4","a6"]),
      dayById("R1"),
      fb("F2", "جسم كامل 2", "مأبضية · ظهر · كتف", ["b3","c1","a2","b2","c5","a5"]),
      dayById("R2"),
      fb("F3", "جسم كامل 3", "ألية · صدر علوي · ظهر", ["d1","a3","c3","d2","c6","d6"]),
      dayById("E")
    ];
  } else if (n === 5){
    list = [dayById("A"), dayById("B"), dayById("R1"), dayById("C"), dayById("D"),
            { key:"E5", name:"اليوم الخامس", focus:"كارديو + نقاط ضعف", rest:false, ex:dayById("E").ex }, dayById("R2")];
  } else list = BASE_DAYS.slice();
  DAYS = list.map(function(d){
    if (d.rest) return d;
    return Object.assign({}, d, { ex:d.ex.map(function(x){
      if (inj.back && x.id === "b3") return cloneEx(exById("d1"), "b3t");        // رفعة رومانية ← دفع الحوض
      if (inj.shoulder && x.id === "a2") return cloneEx(exById("c6"), "a2f");    // ضغط فوق الرأس ← Face pull
      if (!inj.knee && x.id === "b4") x = Object.assign({}, x, { cueI:"b4Gen" });
      return x;
    }) });
  });
  DAYS = DAYS.map(function(d){ return d.rest ? d : applyCust(d); });
  DAYS = DAYS.map(function(d){
    if (d.rest || !state.swap || typeof altEx !== "function") return d;
    return Object.assign({}, d, { ex:d.ex.map(function(x){ return (x.id in state.swap) ? (altEx(x) || x) : x; }) });
  });
  if (!DAYS.some(function(d){ return d.key === state.day; })) state.day = DAYS[0].key;
}
buildDays();

/* صندوق العضلات بثلاث درجات */
function tiersBox(p, s, st){
  var row = function(cls, dot, label, list){
    if (!list || !list.length) return "";
    return '<div class="tier ' + cls + '"><span class="tl"><i class="tdot ' + dot + '"></i>' + label + '</span>' +
           '<span class="tv">' + list.map(mName).join(sep()) + '</span></div>';
  };
  var html = row("t1", "d1", t("lgP"), p) + row("t2", "d2", t("lgS"), s) + row("t3", "d3", t("lgT"), st);
  return html ? '<div class="tiers">' + html + '</div>' : "";
}

/* العضلات التي تجعل العرض يبدأ من الجهة الخلفية */
var BACK_SLUGS = ["hamstrings","glutes","lats","lowerback","triceps","traps","reardelts","calves"];

/* ---------------- render ---------------- */
var rail = document.getElementById("rail");
var grid = document.getElementById("grid");
var dayTitle = document.getElementById("dayTitle");
var daySub = document.getElementById("daySub");
var barFill = document.getElementById("barFill");
var pctEl = document.getElementById("pct");

function currentDay(){
  for (var i = 0; i < DAYS.length; i++){ if (DAYS[i].key === state.day) return DAYS[i]; }
  return DAYS[0];
}
function plan(e){
  var lv = PROF().level, ph2 = state.phase === 2;
  var base = { sets:e.sets, reps:e.reps, rest:e.rest };
  var heavy = e.p2 ? { sets:e.p2.sets, reps:e.p2.reps, rest:e.p2.rest } : base;
  if (lv === "new"){                       // مبتدئ: مجموعة أقل، وبدون المرحلة الثقيلة
    var r = Object.assign({}, base);
    if (!ph2 && r.sets > 2) r.sets -= 1;
    return r;
  }
  if (lv === "exp"){                       // متمرّس: مجموعة زيادة
    var x = Object.assign({}, ph2 ? heavy : base);
    if (x.sets > 1 && x.sets < 5 && !(ph2 && e.p2)) x.sets += 1;
    return x;
  }
  return ph2 ? heavy : base;               // راجع بعد انقطاع: البرنامج الأصلي
}
var _planLevel = plan;
plan = function(e){
  var r;
  if (state.phase === 3){                   // أسابيع 9–12: أثقل وتكرارات أقل
    var saved = state.phase; state.phase = 2; r = Object.assign({}, _planLevel(e)); state.phase = saved;
    if (e.p2){
      var lower = { "6–8":"5–6", "8–10":"6–8", "10":"8" };
      r.reps = lower[r.reps] || r.reps;
      if (/^\d+$/.test(r.rest) && +r.rest < 150) r.rest = "150";
    }
  } else r = Object.assign({}, _planLevel(e));
  if (state.deload && r.sets > 1) r.sets -= 1;   // أسبوع التخفيف
  if (PROF().goal === "fitness") r = fitPlan(r);
  return r;
};
/* هدف «أبني لياقتي»: تكرارات أكثر وراحة أقصر (تحمّل ولياقة) — التمارين بالوقت ما تتغير */
function fitPlan(r){
  var x = Object.assign({}, r), reps = String(x.reps);
  var m = reps.match(/^(\d+)(?:[–-](\d+))?$/);
  if (m){
    var hi = +(m[2] || m[1]);
    x.reps = hi >= 15 ? "15–20" : hi >= 12 ? "15" : "12–15";
  }
  if (/^\d+$/.test(String(x.rest))){
    var rs = Math.round(+x.rest * 0.6 / 15) * 15;
    x.rest = String(Math.max(45, Math.min(rs, 75)));
  }
  return x;
}

function buildRail(){
  rail.innerHTML = "";
  DAYS.forEach(function(d){
    var b = document.createElement("button");
    b.type = "button";
    b.className = "day" + (d.rest ? " rest" : "");
    b.setAttribute("aria-pressed", String(d.key === state.day));
    var dt = dayText(d);
    b.innerHTML = '<span class="letter">' + (d.rest ? "·" : d.key) + '</span>' +
                  '<span><b>' + dt[0] + '</b><em>' + dt[1] + '</em></span>';
    b.addEventListener("click", function(){
      state.day = d.key; save(); buildRail(); buildGrid();
    });
    rail.appendChild(b);
  });
}

function buildGrid(){
  var d = currentDay();
  var dt = dayText(d);
  dayTitle.textContent = d.rest ? t("restDayTitle") : t("dayPrefix") + " " + d.key + " — " + dt[0];
  daySub.textContent = d.rest
    ? t("restDaySub")
    : d.ex.length + " " + t("nExercises") + " · " + dt[1] + " · " + (state.phase === 1 ? t("ph1") : t("ph2"));

  grid.innerHTML = "";
  if (d.rest){ updateProgress(); return; }

  // أول تمرين لم تكتمل مجاميعه = التمرين التالي
  var nextId = null, anyDone = false;
  d.ex.forEach(function(x){
    var px = plan(x), dn = state.sets[state.phase + ":" + x.id] || 0;
    if (dn > 0) anyDone = true;
    if (!nextId && dn < px.sets) nextId = x.id;
  });

  d.ex.forEach(function(e, idx){
    var p = plan(e);
    var key = state.phase + ":" + e.id;
    var done = state.sets[key] || 0;

    var card = document.createElement("article");
    card.className = "card" + (done >= p.sets ? " done" : "") + (e.id === nextId ? " next" : "") + (e.orig ? " alt" : "");

    var stage = document.createElement("div");
    stage.className = "stage";
    stage.appendChild(reel(e.key));
    var tag = document.createElement("span");
    tag.className = "tag";
    tag.textContent = e.orig ? t("altRibbon") : tx(e.id, "t", e.muscle);
    if (e.orig) tag.classList.add("alttag");
    stage.appendChild(tag);
    var mapBox = muscleMap(e.muscles, e.sec, e.stab);
    mapBox.setAttribute("role", "button");
    mapBox.setAttribute("tabindex", "0");
    var nm = names2(e.id, e.ar, e.en);
    mapBox.setAttribute("aria-label", t("zoomAria") + nm[0]);
    mapBox.title = t("zoomHint");
    mapBox.addEventListener("click", function(){ openZoom(e); });
    mapBox.addEventListener("keydown", function(ev){
      if (ev.key === "Enter" || ev.key === " "){ ev.preventDefault(); openZoom(e); }
    });
    stage.appendChild(mapBox);
    card.appendChild(stage);
    card.appendChild(ytLink(e.ar, e.en, e.id, e.key, e));
    card.appendChild(aiAskBtn(e, nm));
    if (typeof cardExtras === "function") card.appendChild(cardExtras(e, p));

    var dots = "";
    for (var i = 1; i <= p.sets; i++){
      dots += '<button type="button" class="dot" data-i="' + i + '" aria-pressed="' +
              (i <= done) + '" aria-label="' + t("setN") + ' ' + i + '">' + i + '</button>';
    }
    var muscleChips = "";

    var body = document.createElement("div");
    body.className = "body";
    body.innerHTML =
      (e.id === nextId ? '<span class="nextpill">' + (anyDone ? t("next") : t("startHere")) + '</span>' : "") +
      '<div class="name"><h3><span class="ord">' + (idx + 1) + '</span>' + nm[0] + (nm[1] ? '<em>' + nm[1] + '</em>' : "") + '</h3>' +
        setsRepsHTML(p) + '</div>' +
      '<p class="cue">' + cueOf(e) + '</p>' +
      '<div class="meta"><span class="chip">' + t("rest") + ' ' + p.rest + (p.rest === "—" ? "" : " " + t("sec")) + '</span>' +
        (e.note ? '<span class="chip">' + tx(e.id, "o", e.note) + '</span>' : "") +
        '</div>' + tiersBox(e.muscles, e.sec, e.stab) +
      '<div class="controls"><div class="dots">' + dots + '</div>' +
        '<label class="kg">' + t("kg") + ' <input type="number" inputmode="decimal" step="0.5" min="0" id="kg-' +
          e.id + '" value="' + (state.kg[e.id] != null ? state.kg[e.id] : "") + '" placeholder="—"></label>' +
      '</div>';
    card.appendChild(body);

    body.querySelectorAll(".dot").forEach(function(btn){
      btn.addEventListener("click", function(){
        var i = parseInt(btn.dataset.i, 10);
        var cur = state.sets[key] || 0;
        var next = (i <= cur) ? i - 1 : i;
        state.sets[key] = next;
        logSet(e, next, p); save(); buildGrid();
        if (next > cur && p.rest !== "—") startRest(parseInt(p.rest, 10), nm[0]);
      });
    });
    var input = body.querySelector("input");
    input.addEventListener("change", function(){
      var v = input.value.trim();
      if (v === "") { delete state.kg[e.id]; } else { state.kg[e.id] = v; }
      logSet(e, state.sets[key] || 0, p); save();
    });

    if (EDIT) card.appendChild(editTools(e));
    if (e.lib != null && !e.orig && !EDIT){ var lt = document.createElement("span"); lt.className = "libtag"; lt.textContent = t("libTag"); stage.appendChild(lt); }
    grid.appendChild(card);
  });
  if (EDIT) grid.appendChild(editAddTile());
  updateProgress();
}

function updateProgress(){
  var d = currentDay();
  if (d.rest){ barFill.style.width = "0%"; pctEl.textContent = "—";
    document.getElementById("startWarm").hidden = true; return; }
  var total = 0, done = 0;
  d.ex.forEach(function(e){
    var p = plan(e);
    total += p.sets;
    done += Math.min(state.sets[state.phase + ":" + e.id] || 0, p.sets);
  });
  var pc = total ? Math.round(done / total * 100) : 0;
  barFill.style.width = pc + "%";
  pctEl.textContent = pc + "%";
  document.getElementById("startWarm").hidden = done > 0;
}

/* ---------------- rest timer ---------------- */
var timer = document.getElementById("timer");
var countEl = document.getElementById("count");
var ringHead = document.getElementById("ringHead");
var timerName = document.getElementById("timerName");
var tick = null, left = 0, span = 0;
var CIRC = 125.66;

function fmt(s){ var mi = Math.floor(s / 60); var r = s % 60; return mi + ":" + (r < 10 ? "0" : "") + r; }
function paint(){
  countEl.textContent = fmt(Math.max(left, 0));
  ringHead.setAttribute("stroke-dashoffset", String(CIRC * (1 - Math.max(left, 0) / span)));
}
function startRest(sec, name, sub){
  document.getElementById("timerSub").textContent = sub || t("nextRound");
  if (!sec || isNaN(sec)) return;
  left = sec; span = sec; timerName.textContent = name || t("timerRest");
  timer.hidden = false; paint();
  if (tick) clearInterval(tick);
  tick = setInterval(function(){
    left--;
    if (left <= 0){ paint(); stopRest(); return; }
    paint();
  }, 1000);
}
function stopRest(){
  if (tick) clearInterval(tick);
  tick = null;
  setTimeout(function(){ timer.hidden = true; }, 400);
}
document.getElementById("skipTime").addEventListener("click", stopRest);
document.getElementById("addTime").addEventListener("click", function(){
  left += 30; span = Math.max(span, left); paint();
});

