/* ---------- بطاقة خطوة بنفس شكل بطاقة التمرين ---------- */
function stepCard(item, idx, opts){
  opts = opts || {};
  var card = document.createElement("article");
  var checked = opts.checkable && !!state.checks[item.id];
  var nm = names2(item.tid, item.ar, item.en);
  card.className = "card" + (checked ? " done" : "") + (opts.isNext ? " next" : "");

  var stage = document.createElement("div");
  stage.className = "stage";
  stage.appendChild(reel(item.key));
  if (item.muscles && item.muscles.length){
    var mapBox = muscleMap(item.muscles, item.sec, item.stab);
    mapBox.setAttribute("role", "button");
    mapBox.setAttribute("tabindex", "0");
    mapBox.title = t("zoomHint");
    mapBox.setAttribute("aria-label", t("zoomAria") + nm[0]);
    mapBox.addEventListener("click", function(){ openZoom(item); });
    mapBox.addEventListener("keydown", function(ev){
      if (ev.key === "Enter" || ev.key === " "){ ev.preventDefault(); openZoom(item); }
    });
    stage.appendChild(mapBox);
  }
  card.appendChild(stage);
  if (item.key) card.appendChild(ytLink(item.ar, item.en, item.tid, item.key, item));

  var body = document.createElement("div");
  body.className = "body";
  body.innerHTML =
    (opts.isNext ? '<span class="nextpill">' + (opts.anyDone ? t("next") : t("startHere")) + '</span>' : "") +
    '<div class="name"><h3>' + (idx != null ? '<span class="ord">' + (idx + 1) + '</span>' : "") +
      nm[0] + (nm[1] ? '<em>' + nm[1] + '</em>' : "") + '</h3>' +
      '<span class="load num"><bdi dir="auto">' + (item.badgeS || tx(item.tid, "b", item.badge)) + '</bdi></span></div>' +
    '<p class="cue">' + (item.cueI ? t(item.cueI) : tx(item.tid, "c", item.cue)) + '</p>' +
    (item.note ? '<div class="meta"><span class="chip">' + tx(item.tid, "o", item.note) + '</span></div>' : "") +
    tiersBox(item.muscles, item.sec, item.stab);

  if (opts.checkable || item.secs){
    var foot = document.createElement("div");
    foot.className = "step-foot";
    if (opts.checkable){
      var cb = document.createElement("button");
      cb.type = "button";
      cb.className = "checkbtn";
      cb.setAttribute("aria-pressed", String(checked));
      cb.textContent = checked ? t("done") : t("markDone");
      cb.addEventListener("click", function(){
        state.checks[item.id] = !state.checks[item.id];
        save();
        opts.onChange && opts.onChange();
      });
      foot.appendChild(cb);
    }
    if (item.secs){
      var tb = document.createElement("button");
      tb.type = "button";
      tb.className = "timebtn";
      tb.textContent = t("startTimer");
      tb.addEventListener("click", function(){ startRest(item.secs, nm[0], t("currentStep")); });
      foot.appendChild(tb);
    }
    body.appendChild(foot);
  }
  card.appendChild(body);
  return card;
}

function renderSteps(list, gridId, barId, pctId){
  var grid = document.getElementById(gridId);
  grid.innerHTML = "";
  var doneCount = 0, nextId = null;
  list.forEach(function(it){
    if (state.checks[it.id]) doneCount++;
    else if (!nextId) nextId = it.id;
  });
  list.forEach(function(it, i){
    grid.appendChild(stepCard(it, i, {
      checkable: true, isNext: it.id === nextId, anyDone: doneCount > 0,
      onChange: function(){ renderSteps(list, gridId, barId, pctId); }
    }));
  });
  document.getElementById(barId).style.width = Math.round(doneCount / list.length * 100) + "%";
  document.getElementById(pctId).textContent = doneCount + "/" + list.length;
}

function renderWarm(){
  renderSteps(WARMUP, "warmGrid", "warmBar", "warmPct");
  renderSteps(COOLDOWN, "coolGrid", "coolBar", "coolPct");
}
document.getElementById("warmReset").addEventListener("click", function(){
  WARMUP.concat(COOLDOWN).forEach(function(it){ delete state.checks[it.id]; });
  save(); renderWarm();
});

/* أوزان البداية حسب الملف: الأرقام الأصلية مضبوطة على رجل راجع بعد انقطاع */
function profWeights(){
  var P = PROF(), f = (P.sex === "f" ? 0.6 : 1) * (P.level === "new" ? 0.8 : P.level === "exp" ? 1.25 : 1);
  var inj = P.inj || {};
  return WEIGHTS.filter(function(it){ return !(inj.shoulder && it.key === "ohp"); }).map(function(it){
    if (f === 1) return it;
    var m = String(it.badge).match(/(\d+)\D+(\d+)/);
    if (!m) return it;
    var step = /legpress|pulldown/.test(it.key) ? 5 : 1;
    var rd = function(x){ var st = step === 1 && x >= 10 ? 2 : step; return Math.max(st === 5 ? 5 : 1, Math.round(x / st) * st); };
    var lo = rd(+m[1] * f), hi = Math.max(lo + (step === 5 ? 5 : 1), rd(+m[2] * f));
    var c = Object.assign({}, it, { badgeS:lo + "–" + hi + " " + t("kgShort") });
    if (it.key === "bench") c.cueI = "wtBenchGen";
    return c;
  });
}
