/* ---------- نوادي قريبة: موقعك + OpenStreetMap + قوقل ماب ---------- */
var GYM_RADS = [2, 5, 10, 20];
var GYM = { busy:false, list:null, pos:null, err:"", r:0, rad:(function(){ try { var v = +localStorage.getItem("coach-gym-rad"); return GYM_RADS.indexOf(v) >= 0 ? v : 5; } catch (e) { return 5; } })() };
