    if (la == null || lo == null) return;
    var name = g.name || g.brand || "";
    var key = (name || "?").toLowerCase() + "|" + la.toFixed(3) + "|" + lo.toFixed(3);
    if (seen[key]) return; seen[key] = 1;
    var adr = [[g["addr:street"], g["addr:housenumber"]].filter(Boolean).join(" "), g["addr:city"]].filter(Boolean).join(", ");
