/* شعار النادي: من موقعه، أو من اسم السلسلة لو معروفة */
var GYM_BRANDS = [["basic-fit","basic-fit.com"],["anytime fitness","anytimefitness.com"],["sportcity","sportcity.nl"],["fit for free","fitforfree.nl"],
  ["trainmore","trainmore.nl"],["david lloyd","davidlloyd.nl"],["snap fitness","snapfitness.com"],["fitland","fitland.nl"],["puregym","puregym.com"],
  ["mcfit","mcfit.com"],["jims","jims.nl"],["fit20","fit20.nl"],["crossfit","crossfit.com"],["the gym","thegymgroup.com"],["planet fitness","planetfitness.com"],
  ["urban gym","urbangym.nl"],["fitness first","fitnessfirst.com"],["clever fit","clever-fit.com"],["kieser","kieser.com"]];
