/* آخر نتيجة تنحفظ نص ساعة، لو سكرت وفتحت تطلع على طول */
var GYM_CACHE = "coach-gym-cache";
function gymCacheKey(lat, lon){ return lat.toFixed(2) + "," + lon.toFixed(2) + "," + GYM.rad + "," + (gymCanGoogle() ? "g" : "o"); }
