    "Output ONLY lines in this exact format, one place per line, no other text:\nNAME | ADDRESS | DISTANCE_KM | RATING | HOURS_TODAY\n" +
    "DISTANCE_KM = straight-line distance from the user in km (number). Use - when unknown. Keep the place name exactly as on Google Maps.";
  var body = { contents:[{ role:"user", parts:[{ text:prompt }] }], tools:[{ googleMaps:{} }],
    toolConfig:{ retrievalConfig:{ latLng:{ latitude:lat, longitude:lon } } }, generationConfig:{ temperature:0.1, maxOutputTokens:4096 } };
  var ms = ["gemini-2.5-flash"].concat(gemModels().filter(function(m){ return m !== "gemini-2.5-flash"; }));
