  var rows = text.split(/\n+/).map(function(l){ return l.replace(/^[\s*\-•\d.)]+/, "").split("|").map(function(x){ return x.trim().replace(/\*\*/g, ""); }); }).filter(function(a){ return a.length >= 3 && a[0]; });
