    var row = rows.filter(function(a){ var n = gymNorm(a[0]); return n && (n === k || n.indexOf(k) >= 0 || k.indexOf(n) >= 0); })[0] || [];
    var d = parseFloat(String(row[2] || "").replace(",", "."));
    var rt = parseFloat(String(row[3] || "").replace(",", "."));
    out.push({ n:m.title, d:isFinite(d) ? d : null, approx:true, adr:row[1] && row[1] !== "-" ? row[1] : "", h:row[4] && row[4] !== "-" ? row[4] : "",
      rating:isFinite(rt) && rt > 0 && rt <= 5 ? rt : null, uri:m.uri || "", pid:String(m.placeId || "").replace(/^places\//, ""), src:"g", dom:gymDomain("", m.title) });
