function bindFoodExtras(host, td){
  host.querySelectorAll("[data-xi]").forEach(function(b){
    b.addEventListener("click", function(){ td.extra.splice(+b.dataset.xi, 1); save(); renderToday(); });
  });
  host.querySelectorAll("[data-mi]").forEach(function(b){
    b.addEventListener("click", function(){
      var f = state.myFoods.splice(+b.dataset.mi, 1)[0];
      if (f && td.food[f.id]) delete td.food[f.id];
      save(); renderToday();
    });
  });
  var form = document.getElementById("fxForm");
  var read = function(){
    return { n:document.getElementById("fxN").value.trim(), p:numIn(document.getElementById("fxP").value), k:numIn(document.getElementById("fxK").value) };
  };
  var valid = function(v){ return v.n && v.p != null && v.k != null && v.p >= 0 && v.p <= 300 && v.k >= 0 && v.k <= 5000; };
  var done = function(){ FX = { open:false, busy:false, note:"", vals:null }; save(); renderToday(); };
  document.getElementById("fxAdd").addEventListener("click", function(){
    FX.open = true; FX.note = ""; FX.vals = null; form.hidden = false; document.getElementById("fxN").focus();
  });
  document.getElementById("fxCancel").addEventListener("click", function(){ FX = { open:false, busy:false, note:"", vals:null }; renderToday(); });
  document.getElementById("fxToday").addEventListener("click", function(){
    var v = read(); if (!valid(v)){ document.getElementById("fxErr").hidden = false; return; }
    td.extra = td.extra || []; td.extra.push({ n:v.n.slice(0, 40), p:Math.round(v.p), k:Math.round(v.k) }); done();
  });
  document.getElementById("fxMine").addEventListener("click", function(){
    var v = read(); if (!valid(v)){ document.getElementById("fxErr").hidden = false; return; }
    state.myFoods = state.myFoods || [];
    var id = "u" + Date.now().toString(36);
    state.myFoods.push({ id:id, n:v.n.slice(0, 40), p:Math.round(v.p), k:Math.round(v.k) });
    td.food[id] = (td.food[id] || 0) + 1; done();
  });
  var pl = document.getElementById("fxPhotoLink");
  if (pl) pl.addEventListener("click", function(){ aiOpen(null, ""); });
  var ph = document.getElementById("fxPhoto");
  if (ph) ph.addEventListener("change", function(){
    var file = ph.files && ph.files[0]; if (!file || FX.busy) return;
    FX = { open:true, busy:true, note:'<span class="ai-dots"><i></i><i></i><i></i></span> ' + t("photoWorking"), vals:null };
    renderToday();
    var lang = LANG === "ar" ? "Arabic" : langName();
    AI.sample.json("Look at this photo of a meal. Estimate the TOTAL protein (grams) and calories (kcal) of everything visible on the plate. " +
      "Reply with only JSON: {\"name\": short dish name in " + lang + " (max 5 words), \"protein_g\": number, \"kcal\": number}. Example: {\"name\":\"Rice with chicken\",\"protein_g\":42,\"kcal\":610}",
      { images:file })
      .then(function(r){
        var p = numIn(r && (r.protein_g != null ? r.protein_g : r.protein)), k = numIn(r && (r.kcal != null ? r.kcal : r.calories));
        if (p == null || k == null) throw { code:"invalid_json" };
        FX = { open:true, busy:false, note:t("photoCheck"), vals:{ n:String(r.name || "").slice(0, 40), p:Math.round(p), k:Math.round(k) } };
        renderToday();
      })
      .catch(function(e){
        var c = e && e.code;
        FX = { open:true, busy:false, note:(c && /^(not_granted|sampling_disabled|bad_key|rate_limited|offline|region)$/.test(c)) ? aiErrText(c) : (c === "images_unavailable") ? t("photoNA") : t("photoFail"), vals:null };
        renderToday();
      });
  });
}

/* ---------------- 8) قائمة المشتريات ---------------- */
function renderGroc(){
  var host = document.getElementById("grocList"); if (!host) return;
  var days = state.grocDays === 5 ? 5 : 7, per = {};
  MEALS.forEach(function(m){ Object.keys(m.items).forEach(function(id){ per[id] = (per[id] || 0) + m.items[id]; }); });
  state.groc = state.groc || {};
  var rows = [], text = [];
  (window.GROC || []).forEach(function(g){
    if (!per[g.id]) return;
    var portions = per[g.id] * days, total = portions * g.per;
    var packs = Math.max(1, Math.ceil(total / g.pack - 0.001));
    var L = g[LANG] || (LANG === "ar" ? g.ar : g.en), unit = (g.u || {})[LANG] || (LANG === "ar" ? "" : (g.u || {}).en) || "";
    var on = !!state.groc[g.id];
    rows.push('<li><button type="button" class="gr-it" data-g="' + g.id + '" aria-pressed="' + on + '">' +
      '<span class="hbox">' + (on ? ICONS.check : "") + '</span><span class="gr-n">' + xEsc(L[0]) + ' <i>· ' + xEsc(L[1]) + '</i></span>' +
      '<b class="gr-q num"><bdi dir="ltr">×' + packs + '</bdi></b>' +
      '<small>' + fill(t("grocWeek"), { q:'<bdi dir="ltr">' + nf(total) + '</bdi> ' + xEsc(unit) }) + '</small></button></li>');
    text.push("- " + L[0] + ": " + packs + " × " + L[1]);
  });
  host.innerHTML = '<div class="panel gr">' +
    '<div class="gr-head"><div class="seg" role="group">' +
      [5, 7].map(function(n){ return '<button type="button" data-gd="' + n + '" aria-pressed="' + (days === n) + '"><bdi dir="ltr">' + n + '</bdi> ' + t("grocDays") + '</button>'; }).join("") +
    '</div><div class="gr-acts"><button type="button" class="icon-btn" id="grCopy">' + t("grocCopy") + '</button>' +
      '<button type="button" class="icon-btn" id="grReset">' + t("grocReset") + '</button></div></div>' +
    '<ul class="gr-list">' + rows.join("") + '</ul></div>';
  host.querySelectorAll("[data-gd]").forEach(function(b){ b.addEventListener("click", function(){ state.grocDays = +b.dataset.gd; save(); renderGroc(); }); });
  host.querySelectorAll(".gr-it").forEach(function(b){ b.addEventListener("click", function(){ state.groc[b.dataset.g] = !state.groc[b.dataset.g]; save(); renderGroc(); }); });
  document.getElementById("grReset").addEventListener("click", function(){ state.groc = {}; save(); renderGroc(); });
  document.getElementById("grCopy").addEventListener("click", function(){
    var s = t("grocTitle") + " (" + days + " " + t("grocDays") + ")\n" + text.join("\n");
    var ok = function(){ var b = document.getElementById("grCopy"); b.textContent = t("grocCopied"); setTimeout(function(){ b.textContent = t("grocCopy"); }, 1600); };
    var fb = function(){ var ta = document.createElement("textarea"); ta.value = s; ta.style.position = "fixed"; ta.style.opacity = "0"; document.body.appendChild(ta); ta.select(); try { document.execCommand("copy"); ok(); } catch (e) {} ta.remove(); };
    try { navigator.clipboard.writeText(s).then(ok, fb); } catch (e) { fb(); }
  });
}

/* ---------------- 4) تقدّمي ---------------- */
var PG = { mOff:0, chartId:null };
function lineChart(points, label){
  var W = 640, H = 220, L = 44, R = 14, T = 14, B = 34;
  var ks = points.map(function(x){ return x.v; });
  var lo = Math.min.apply(null, ks), hi = Math.max.apply(null, ks);
  var pad = Math.max(1, (hi - lo) * 0.15); lo = Math.floor(lo - pad); hi = Math.ceil(hi + pad);
  var n = points.length;
  var X = function(i){ return L + (W - L - R) * (n === 1 ? 0.5 : i / (n - 1)); };
  var Y = function(v){ return T + (H - T - B) * (hi - v) / (hi - lo); };
  var grid = "", step = Math.max(1, Math.round((hi - lo) / 4));
  for (var v = hi; v >= lo; v -= step) grid += '<line class="gl" x1="' + L + '" x2="' + (W - R) + '" y1="' + Y(v) + '" y2="' + Y(v) + '"/><text class="ax" x="' + (L - 8) + '" y="' + (Y(v) + 4) + '" text-anchor="end">' + v + '</text>';
  var every = Math.ceil(n / 6);
  points.forEach(function(p, i){ if (i % every === 0 || i === n - 1) grid += '<text class="ax" x="' + X(i) + '" y="' + (H - B + 18) + '" text-anchor="middle">' + xEsc(fmtDate(p.d)) + '</text>'; });
  var line = points.map(function(p, i){ return (i ? "L" : "M") + X(i).toFixed(1) + " " + Y(p.v).toFixed(1); }).join(" ");
  var dots = points.map(function(p, i){ return '<circle class="dot" cx="' + X(i) + '" cy="' + Y(p.v) + '" r="4.5"><title>' + xEsc(fmtDate(p.d)) + ': ' + p.v + '</title></circle>'; }).join("");
  var last = points[n - 1];
  return '<svg class="wchart" viewBox="0 0 ' + W + ' ' + H + '" dir="ltr" role="img" aria-label="' + xEsc(label) + '">' + grid +
    '<path class="wl" d="' + line + '"/>' + dots +
    '<text class="lastlab" x="' + Math.min(X(n - 1), W - R - 4) + '" y="' + (Y(last.v) - 10) + '" text-anchor="end">' + last.v + '</text></svg>';
}
function prList(){
  var best = {};
  histDates().forEach(function(d){
    var ex = state.hist[d].ex;
    Object.keys(ex).forEach(function(id){
      var r = ex[id]; if (!r.kg) return;
      if (!best[id]) best[id] = { id:id, kg:r.kg, date:d, rec:r, first:r.kg, n:1 };
      else { best[id].n++; if (r.kg > best[id].kg){ best[id].kg = r.kg; best[id].date = d; best[id].rec = r; } }
    });
  });
  return Object.keys(best).map(function(k){ return best[k]; }).sort(function(a, b){ return a.date < b.date ? 1 : -1; });
}
function renderProgress(){
  if (!document.getElementById("pgStats")) return;
  var dates = histDates(), today = todayISO(), wk = mondayOf(today);
  var thisWeek = dates.filter(function(d){ return d >= wk; }).length;
  var weeks = {}; dates.forEach(function(d){ weeks[mondayOf(d)] = 1; });
  var streak = 0, cur = new Date(wk + "T12:00:00");
  if (!weeks[wk]) cur.setDate(cur.getDate() - 7);
  while (weeks[isoOf(cur)]){ streak++; cur.setDate(cur.getDate() - 7); }
  var prs = prList();
  var tile = function(lbl, v){ return '<div class="tile"><span>' + lbl + '</span><b class="num"><bdi dir="ltr">' + v + '</bdi></b></div>'; };
  document.getElementById("pgStats").innerHTML = '<div class="tiles four">' + tile(t("stWeek"), thisWeek) + tile(t("stTotal"), dates.length) + tile(t("stStreak"), streak) + tile(t("stPR"), prs.filter(function(p){ return p.kg > p.first; }).length) + '</div>';

  /* التقويم */
  var base = new Date(); base.setDate(1); base.setMonth(base.getMonth() + PG.mOff);
  var y = base.getFullYear(), m = base.getMonth(), first = new Date(y, m, 1), lead = (first.getDay() + 6) % 7, nd = new Date(y, m + 1, 0).getDate();
  var cells = "", set = {}; dates.forEach(function(d){ set[d] = state.hist[d].day; });
  for (var i = 0; i < lead; i++) cells += '<span class="cd empty"></span>';
  for (var dd = 1; dd <= nd; dd++){
    var iso = isoOf(new Date(y, m, dd));
    cells += '<span class="cd' + (set[iso] ? " on" : "") + (iso === today ? " tdy" : "") + '"' + (set[iso] ? ' title="' + t("dayPrefix") + " " + xEsc(set[iso]) + '"' : "") + '><bdi dir="ltr">' + dd + '</bdi>' + (set[iso] ? '<i>' + xEsc(set[iso]) + '</i>' : "") + '</span>';
  }
  var calDays = t("calDays");
  document.getElementById("pgCal").innerHTML = '<div class="cal-head"><button type="button" class="ai-ib" id="calPrev" aria-label="‹">‹</button><h3>' +
    first.toLocaleDateString(locale(), { month:"long", year:"numeric" }) + '</h3><button type="button" class="ai-ib" id="calNext" aria-label="›"' + (PG.mOff >= 0 ? " disabled" : "") + '>›</button></div>' +
    '<div class="cal" dir="' + (LANG === "ar" ? "rtl" : "ltr") + '">' + (Array.isArray(calDays) ? calDays : []).map(function(x){ return '<span class="cw">' + x + '</span>'; }).join("") + cells + '</div>' +
    '<p class="pg-note">' + t("calLegend") + '</p>';
  var rtl = LANG === "ar";
  document.getElementById("calPrev").addEventListener("click", function(){ PG.mOff -= 1; renderProgress(); });
  document.getElementById("calNext").addEventListener("click", function(){ PG.mOff = Math.min(0, PG.mOff + 1); renderProgress(); });
  if (rtl){ document.getElementById("calPrev").textContent = "›"; document.getElementById("calNext").textContent = "‹"; }

  /* الأرقام القياسية */
  var weekAgo = isoOf(new Date(Date.now() - 7 * 864e5));
  document.getElementById("pgPR").innerHTML = '<h3>' + t("prTitle") + '</h3>' + (prs.length ? '<ul class="pr-list">' + prs.slice(0, 10).map(function(p){
    return '<li><span>' + xEsc(recName(p.rec, p.id)) + (p.date >= weekAgo && p.kg > p.first ? ' <em class="pr-new">' + t("prNew") + '</em>' : "") + '</span><b>' + kgTxt(p.kg) + '</b><small>' + fmtDate(p.date) + '</small></li>';
  }).join("") + '</ul>' : '<p class="pg-note">' + t("prEmpty") + '</p>');

  /* الرسم */
  var withKg = prs.filter(function(p){ return p.n >= 1; });
  if (!PG.chartId || !withKg.some(function(p){ return p.id === PG.chartId; })){
    var most = withKg.slice().sort(function(a, b){ return b.n - a.n; })[0]; PG.chartId = most ? most.id : null;
  }
  var ch = '<div class="pg-ch-head"><h3>' + t("chartTitle") + '</h3>' + (withKg.length ? '<select id="pgSel">' + withKg.map(function(p){
    return '<option value="' + xEsc(p.id) + '"' + (p.id === PG.chartId ? " selected" : "") + '>' + xEsc(recName(p.rec, p.id)) + '</option>'; }).join("") + '</select>' : "") + '</div>';
  var pts = PG.chartId ? sessionsOf(PG.chartId).filter(function(x){ return x.kg; }).map(function(x){ return { d:x.date, v:x.kg }; }) : [];
  ch += pts.length >= 2 ? '<div class="wplot">' + lineChart(pts, t("chartTitle")) + '</div>' : '<p class="pg-note">' + (withKg.length ? t("chartEmpty") : t("prEmpty")) + '</p>';
  document.getElementById("pgChart").innerHTML = ch;
  var sel = document.getElementById("pgSel");
  if (sel) sel.addEventListener("change", function(){ PG.chartId = sel.value; renderProgress(); });

  /* بعد الـ8 أسابيع */
  var wkN = dates.length ? Math.floor(daysBetween(dates[0], today) / 7) + 1 : 0;
  document.getElementById("pgNext").innerHTML = '<h3>' + t("nextTitle") + '</h3><p>' + t("nextText") + '</p>' +
    '<p class="pg-note">' + (wkN ? fill(t("weekNow"), { n:'<bdi dir="ltr">' + wkN + '</bdi>' }) : t("weekNone")) + '</p>' +
    (state.deload ? '<p class="ss-deload">' + t("deloadOn") + '</p>' : "") +
    '<div class="pg-btns"><button type="button" class="' + (state.deload ? "icon-btn" : "startbtn") + '" id="pgDeload">' + t(state.deload ? "deloadOff" : "deloadBtn") + '</button>' +
    (state.phase !== 3 ? '<button type="button" class="icon-btn" id="pgPh3">' + t("ph3Btn") + '</button>' : "") + '</div>';
  document.getElementById("pgDeload").addEventListener("click", function(){ state.deload = !state.deload; save(); buildGrid(); renderProgress(); });
  var p3 = document.getElementById("pgPh3");
  if (p3) p3.addEventListener("click", function(){ state.deload = false; setPhase(3); });

  renderMeas(); renderPhotos(); renderReport(); renderData();
}

