/* ---------------- 11) المزامنة + 12) النسخة الاحتياطية ---------------- */
var SY = { ref:null, busy:false, pending:false, timer:0, status:"off", last:0, first:true };
function syncRender(){
  var el = document.getElementById("syncSt"); if (!el) return;
  var cls = SY.status === "on" ? "ok" : SY.status === "err" ? "warn" : "";
  var txt = SY.status === "on" ? t("syncOn") + (SY.last ? " · " + fill(t("syncLast"), { t:new Date(SY.last).toLocaleTimeString(locale(), { hour:"2-digit", minute:"2-digit" }) }) : "")
          : SY.status === "syncing" ? t("syncing") : SY.status === "err" ? t("syncErr") : t("syncOff");
  el.className = "wstatus " + cls; el.textContent = txt;
}
function trimForSync(s){
  var c = JSON.parse(JSON.stringify(s)), cut = isoOf(new Date(Date.now() - 400 * 864e5));
  ["hist","foodLog"].forEach(function(k){ if (c[k]) Object.keys(c[k]).forEach(function(d){ if (d < cut) delete c[k][d]; }); });
  return c;
}
function syncPush(){
  if (!SY || !SY.ref) return;
  clearTimeout(SY.timer); SY.timer = setTimeout(syncPushNow, 1500);
}
function syncPushNow(){
  if (!SY.ref) return Promise.resolve();
  if (SY.busy){ SY.pending = true; return Promise.resolve(); }
  SY.busy = true; SY.status = "syncing"; syncRender();
  if (!state._ts) state._ts = Date.now();
  return SY.ref.set({ json:JSON.stringify(trimForSync(state)), ts:state._ts, v:1 })
    .then(function(){ SY.status = "on"; SY.last = Date.now(); })
    .catch(function(){ SY.status = "err"; })
    .then(function(){ SY.busy = false; syncRender(); if (SY.pending){ SY.pending = false; syncPushNow(); } });
}
function adoptState(ns){
  state = Object.assign({ phase:1, day:"A", sets:{}, kg:{}, checks:{}, weights:[], today:null }, ns);
  var iso = todayISO();
  if (state.setsDate !== iso){ state.sets = {}; state.setsDate = iso; }
  if (LANGS.indexOf(state.lang) >= 0) LANG = state.lang;
  saveLocal();
  if (state.profile && !profEl.hidden && profFirst){ profFirst = false; profEl.hidden = true; }
  NEED_PROFILE = !state.profile;
  state.phase = (state.phase === 2 || state.phase === 3) ? state.phase : 1;
  [1,2,3].forEach(function(n){ document.getElementById("ph" + n).setAttribute("aria-pressed", String(state.phase === n)); });
  if (typeof applyTheme === "function") try { applyTheme(); } catch (e) {}
  buildDays(); renderAll();
}
function applyRemote(snap){
  var first = SY.first; SY.first = false;
  if (!snap || !snap.exists){ if (first) syncPushNow(); return; }
  var d = snap.data(); if (!d || typeof d.json !== "string") return;
  var rts = +d.ts || 0, lts = +state._ts || 0, rs;
  try { rs = JSON.parse(d.json); } catch (e) { return; }
  var localEmpty = !Object.keys(state.hist || {}).length && !(state.weights || []).length && !(state.meas || []).length;
  var remoteHas = Object.keys(rs.hist || {}).length || (rs.weights || []).length || rs.profile;
  if (rts > lts || (first && localEmpty && remoteHas && rts !== lts)){ adoptState(rs); SY.status = "on"; SY.last = Date.now(); syncRender(); }
  else if (first && lts > rts) syncPushNow();
  else { SY.status = "on"; SY.last = Date.now(); syncRender(); }
}
function syncStart(){
  if (!window.claude || typeof window.claude.use !== "function"){ syncRender(); return; }
  Promise.all([window.claude.use("db"), window.claude.use("user")]).then(function(r){
    var db = r[0], us = r[1];
    if (!db || !us) return;
    return us.id().then(function(uid){
      if (!uid) return;
      SY.ref = db.doc("data/users/" + uid + "/state");
      SY.status = "syncing"; syncRender();
      SY.ref.onSnapshot(function(sn){ if (!sn.metadata || !sn.metadata.hasPendingWrites) applyRemote(sn); },
                        function(){ SY.status = "err"; syncRender(); });
    });
  }).catch(function(){ SY.status = SY.ref ? "err" : "off"; syncRender(); });
}
var BK = { pending:null, msg:"" };
function renderData(){
  var host = document.getElementById("pgData");
  host.innerHTML = '<p id="syncSt" class="wstatus"></p>' +
    '<div class="pg-btns"><button type="button" class="startbtn" id="bkOut">' + t("bkExport") + '</button>' +
    '<label class="icon-btn">' + t("bkImport") + '<input type="file" accept="application/json,.json" id="bkIn" hidden></label></div>' +
    (BK.pending ? '<div class="bk-confirm"><p>' + t("bkConfirm") + '</p><div class="pg-btns"><button type="button" class="startbtn" id="bkYes">' + t("bkYes") + '</button><button type="button" class="icon-btn" id="bkNo">' + t("cancel") + '</button></div></div>' : "") +
    (BK.msg ? '<p class="pg-note">' + BK.msg + '</p>' : "");
  syncRender();
  document.getElementById("bkOut").addEventListener("click", exportBackup);
  document.getElementById("bkIn").addEventListener("change", function(){
    var f = this.files && this.files[0]; if (!f) return;
    var rd = new FileReader();
    rd.onload = function(){
      var o = null; try { o = JSON.parse(rd.result); } catch (e) {}
      if (!o || o.app !== "sehati" || !o.state || typeof o.state !== "object"){ BK = { pending:null, msg:t("bkBad") }; renderData(); return; }
      BK = { pending:o, msg:"" }; renderData();
    };
    rd.readAsText(f);
  });
  var y = document.getElementById("bkYes");
  if (y) y.addEventListener("click", function(){
    var o = BK.pending; BK = { pending:null, msg:t("bkOk") };
    var photos = Array.isArray(o.photos) ? o.photos : [];
    var ns = o.state; ns._ts = Date.now();
    adoptState(ns); syncPushNow();
    if (photos.length) idbDo("readwrite", function(st){ photos.forEach(function(p){ if (p && p.id && p.data) st.put(p); }); }).then(renderPhotos).catch(function(){});
  });
  var n = document.getElementById("bkNo");
  if (n) n.addEventListener("click", function(){ BK = { pending:null, msg:"" }; renderData(); });
}
function exportBackup(){
  idbAll().catch(function(){ return []; }).then(function(photos){
    var data = JSON.stringify({ app:"sehati", v:1, at:new Date().toISOString(), state:state, photos:photos });
    var name = "coach-backup-" + todayISO() + ".json", blob = new Blob([data], { type:"application/json" });
    var fallback = function(){
      var a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = name;
      document.body.appendChild(a); a.click();
      setTimeout(function(){ URL.revokeObjectURL(a.href); a.remove(); }, 1500);
    };
    var dlp = (window.claude && typeof window.claude.use === "function") ? window.claude.use("downloads") : Promise.resolve(null);
    dlp.then(function(dl){
      if (!dl){ fallback(); return; }
      return dl.save({ filename:name, data:blob }).then(function(){ BK.msg = t("bkSaved"); renderData(); }, function(){});
    }).catch(fallback);
  });
}

