var LIB = window.LIB || [];
function pad3(n){ return String(n).padStart(3, "0"); }
function libKey(n){ return "L" + pad3(n); }
function isLibKey(k){ return /^L\d{3}$/.test(String(k)); }
LIB.forEach(function(L){
  var k = libKey(L.n), th = (window.LIB_T || {})[pad3(L.n)];
  if (th){ CARD_POSTER[k] = th; VIDEO_POSTER[k] = th; }
  VIDEO_WIDE[k] = true; VIDEO_CREDIT[k] = "Lyfta";
});

/* الفيديو: في الموقع من ملفات مجمّعة (5 فيديوهات بكل ملف)، وفي ملف الجهاز من مجلد صحتي-videos/lib */
var LIBPACK = {};
function libVideo(n){
  if (window.VIDEO_BASE) return Promise.resolve(window.VIDEO_BASE + "lib/" + pad3(n) + ".mp4");
  var p = Math.floor(n / 5);
  if (!LIBPACK[p]){
    LIBPACK[p] = fetch("lib/p" + p + ".mp4").then(function(r){ if (!r.ok) throw new Error("pack"); return r.arrayBuffer(); }).then(function(buf){
      var len = parseInt(new TextDecoder().decode(new Uint8Array(buf, 0, 12)), 10);
      var idx = JSON.parse(new TextDecoder().decode(new Uint8Array(buf, 12, len)));
      var base = 12 + len, urls = {};
      idx.forEach(function(e){ urls[e.n] = URL.createObjectURL(new Blob([buf.slice(base + e.off, base + e.off + e.len)], { type:"video/mp4" })); });
      return urls;
    });
    LIBPACK[p].catch(function(){ delete LIBPACK[p]; });
  }
  return LIBPACK[p].then(function(u){ return u[n]; });
}

/* الجسم من طبقات: صورة الجسم + طبقة حمراء لكل عضلة (لأي مجموعة عضلات) */
function bodyStack(side, p, s, st, cls, label){
  var B = window.BODY_LAYERS, base = B.base[side];
  var box = document.createElement("span");
  box.className = "bodyimg bstack " + (cls || "");
  box.setAttribute("role", "img"); box.setAttribute("aria-label", label || "");
  box.style.aspectRatio = base.w + " / " + base.h;
  var add = function(src, L, klass){
    var im = document.createElement("img");
    im.src = src; im.alt = ""; im.className = klass; im.decoding = "async";
    if (L){ im.style.left = L.x + "%"; im.style.top = L.y + "%"; im.style.width = L.w + "%"; im.style.height = L.h + "%"; }
    box.appendChild(im);
  };
  add(base.src, null, "bs-base");
  [[st, "bs-t"], [s, "bs-s"], [p, "bs-p"]].forEach(function(pair){
    (pair[0] || []).forEach(function(m){ var L = (B.L[m] || {})[side]; if (L) add(L.src, L, pair[1]); });
  });
  return box;
}

/* تمرين من المكتبة داخل البرنامج */
function regLibTRX(id, L){
  var TR = window.TRX = window.TRX || {};
  LANGS.forEach(function(l){
    if (l === "ar") return;
    TR[l] = TR[l] || {};
    var ML = (window.MUSCLES_L || {})[l] || {};
    TR[l][id] = { n:L[l] || (((window.LIB_L || {})[l] || [])[L.n]) || L.en, t:L.p.map(function(k){ return ML[k] || k; }).join(" · ") };
  });
}
function libEx(n, src, id){
  var L = (window.LIB || [])[n]; if (!L) return null;
  regLibTRX(id, L);
  src = src || {};
  var g = L.g === "quads" || L.g === "hamstrings" || L.g === "glutes" ? "legs" : L.g;
  return { id:id, tid:id, ar:L.ar, en:L.en, key:libKey(n), lib:n,
    muscle:L.p.map(function(k){ return MUSCLE_AR[k] || k; }).join(" · "),
    muscles:L.p, sec:L.s, stab:[],
    sets:+src.sets || L.d[0], reps:String(src.reps || L.d[1]), rest:String(src.rest || L.d[2]),
    cue:(((window.I18N || {}).ar || {})["cue_" + g]) || "", cueI:"cue_" + g,
    p2:(!src.sets && L.d[2] === "90" && /^\d+$/.test(String(L.d[1]))) ? { sets:4, reps:"6–8", rest:"120" } : null, note:null };   // تمرين مركّب: مرحلة ثقيلة مثل البرنامج
}
function baseIdOf(x){ if (x.orig) x = x.orig; return x.repOf || x.id; }
function applyCust(d){
  var C = state.cust || {}, rm = C.rm || {}, rep = C.rep || {};
  var ex = [];
  d.ex.forEach(function(x){
    var b = baseIdOf(x);
    if (rm[b]) return;
    if (rep[b]){
      var o = x.orig || x, e = libEx(rep[b].L, o, b + "~L" + rep[b].L);
      if (e){ e.repOf = b; e.repName = names2(o.tid || o.id, o.ar, o.en)[0]; ex.push(e); return; }
    }
    ex.push(x);
  });
  ((C.add || {})[d.key] || []).forEach(function(a){
    var e = libEx(a.L, a, "A" + a.u);
    if (e){ e.addU = a.u; ex.push(e); }
  });
  return Object.assign({}, d, { ex:ex });
}
function custSave(){ save(); buildDays(); buildGrid(); if (typeof renderProgress === "function") renderProgress(); }

