var LIB_GROUPS = ["chest","back","shoulders","biceps","triceps","forearms","abs","legs","calves","cardio"];
var LIB_EQ = ["db","bar","cable","machine","body"];
function libGroup(L){ return (L.g === "quads" || L.g === "hamstrings" || L.g === "glutes") ? "legs" : L.g; }
function normTxt(s){ return String(s || "").toLowerCase().replace(/[ً-ْـ]/g, "").replace(/[أإآ]/g, "ا").replace(/ة/g, "ه").replace(/ى/g, "ي"); }
function libName(L){ return L[LANG] || (((window.LIB_L || {})[LANG] || [])[L.n]) || L.en; }
function libList(){
  var q = normTxt(LV.q).trim().split(/\s+/).filter(Boolean);
  return LIB.filter(function(L){
    if (LV.g !== "all" && libGroup(L) !== LV.g) return false;
    if (LV.eq !== "all" && L.eq !== LV.eq) return false;
    if (!q.length) return true;
    var hay = normTxt(L.ar + " " + L.en + " " + L.nl + " " + (LANG in {ar:1,nl:1,en:1} ? "" : libName(L)) + " " + L.p.map(function(k){ return MUSCLE_AR[k] + " " + mName(k); }).join(" "));
    return q.every(function(w){ return hay.indexOf(w) >= 0; });
  });
}
